
.entry-shell {
  min-height: 100vh;
  padding: 18px;
  background:
    linear-gradient(180deg, rgba(7, 13, 22, 0.9), rgba(15, 25, 44, 0.95)),
    radial-gradient(circle at top, rgba(124, 199, 255, 0.18), transparent 32%);
  color: #edf6ff;
  font-family: 'LXGW WenKai', 'Microsoft YaHei', sans-serif;
}

.entry-card {
  width: min(940px, 100%);
  margin: 0 auto;
  border-radius: 30px;
  border: 1px solid rgba(124, 199, 255, 0.25);
  background:
    linear-gradient(180deg, rgba(20, 31, 51, 0.94), rgba(14, 22, 36, 0.96)),
    radial-gradient(circle at top right, rgba(136, 255, 214, 0.15), transparent 28%);
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.35);
  padding: 24px;
}

.hero h1 {
  margin: 8px 0 12px;
  font-size: clamp(28px, 4vw, 44px);
}

.hero p {
  max-width: 720px;
  margin: 0;
  line-height: 1.8;
  color: rgba(237, 246, 255, 0.82);
}

.eyebrow {
  color: #88ffd6;
  letter-spacing: 0.22em;
  font-size: 12px;
}

.panel-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field span {
  color: #a9c5e4;
  font-size: 13px;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  border-radius: 18px;
  border: 1px solid rgba(124, 199, 255, 0.2);
  background: rgba(8, 14, 23, 0.68);
  color: #edf6ff;
  padding: 14px 16px;
  outline: none;
}

.wide {
  margin-top: 14px;
}

.tips {
  margin-top: 18px;
  display: grid;
  gap: 8px;
  color: #b8cadf;
  font-size: 13px;
}

.error-box {
  margin-top: 16px;
  border-radius: 16px;
  border: 1px solid rgba(255, 143, 143, 0.3);
  background: rgba(255, 143, 143, 0.08);
  color: #ffd5d5;
  padding: 12px 14px;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 20px;
}

.actions button {
  border-radius: 999px;
  padding: 12px 20px;
  cursor: pointer;
}

.ghost {
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.04);
  color: #edf6ff;
}

.primary {
  border: 1px solid rgba(136, 255, 214, 0.4);
  background: linear-gradient(90deg, rgba(124, 199, 255, 0.28), rgba(136, 255, 214, 0.26));
  color: #edf6ff;
}

@media (max-width: 720px) {
  .entry-shell {
    padding: 10px;
  }

  .entry-card {
    padding: 18px;
    border-radius: 22px;
  }

  .panel-grid {
    grid-template-columns: 1fr;
  }

  .actions {
    flex-direction: column;
  }
}
